class Interval:
    """A half-open interval [start, end) on the number line."""

    __slots__ = ("start", "end")

    def __init__(self, start, end):
        if end < start:
            raise ValueError("interval end precedes start")
        self.start = start
        self.end = end

    def overlaps(self, other):
        """Return True when the two intervals share at least one point."""
        return self.start < other.end and other.start < self.end

    def length(self):
        return self.end - self.start


def schedule_maximum(intervals):
    """Choose the largest subset of intervals in which no two overlap.

    The classic greedy algorithm sorts by end time and repeatedly takes the
    first interval that starts at or after the end of the last one taken.
    """
    ordered = sorted(intervals, key=lambda item: (item.end, item.start))
    chosen = []
    free_at = None
    for item in ordered:
        if free_at is None or item.start >= free_at:
            chosen.append(item)
            free_at = item.end
    return chosen


class TokenBucket:
    """Allow bursts of traffic while enforcing an average rate."""

    def __init__(self, capacity, refill_per_second):
        self.capacity = float(capacity)
        self.refill = float(refill_per_second)
        self.tokens = self.capacity
        self.updated = 0.0

    def allow(self, now, cost=1.0):
        """Consume tokens at time `now`; return False when the bucket is empty."""
        elapsed = max(0.0, now - self.updated)
        self.tokens = min(self.capacity, self.tokens + elapsed * self.refill)
        self.updated = now
        if self.tokens >= cost:
            self.tokens -= cost
            return True
        return False


def merge_sorted(left, right, key=None):
    """Merge two sorted sequences into one sorted sequence in linear time."""
    key = key or (lambda item: item)
    result = []
    i = j = 0
    while i < len(left) and j < len(right):
        if key(left[i]) <= key(right[j]):
            result.append(left[i])
            i += 1
        else:
            result.append(right[j])
            j += 1
    result.extend(left[i:])
    result.extend(right[j:])
    return result


def word_frequencies(text, stop_words=()):
    """Count words case-insensitively, ignoring punctuation and stop words."""
    counts = {}
    for raw in text.lower().split():
        word = "".join(ch for ch in raw if ch.isalnum())
        if word and word not in stop_words:
            counts[word] = counts.get(word, 0) + 1
    return counts


def longest_common_prefix(strings):
    """Return the longest prefix shared by every string in the list."""
    if not strings:
        return ""
    first = min(strings)
    last = max(strings)
    for index, character in enumerate(first):
        if character != last[index]:
            return first[:index]
    return first


def binary_search(values, target):
    """Return the index of `target` in sorted `values`, or -1 when absent."""
    low, high = 0, len(values) - 1
    while low <= high:
        middle = (low + high) // 2
        if values[middle] == target:
            return middle
        if values[middle] < target:
            low = middle + 1
        else:
            high = middle - 1
    return -1


def depth_first_order(graph, start):
    """Visit every node reachable from `start` in depth-first order."""
    seen = set()
    order = []
    stack = [start]
    while stack:
        node = stack.pop()
        if node in seen:
            continue
        seen.add(node)
        order.append(node)
        for neighbor in sorted(graph.get(node, ()), reverse=True):
            if neighbor not in seen:
                stack.append(neighbor)
    return order


def compress_runs(text):
    """Replace runs of repeated characters with a count and the character."""
    parts = []
    index = 0
    while index < len(text):
        run = 1
        while index + run < len(text) and text[index + run] == text[index]:
            run += 1
        if run > 1:
            parts.append(str(run) + text[index])
        else:
            parts.append(text[index])
        index += run
    return "".join(parts)


def restore_runs(compressed):
    """Inverse of compress_runs."""
    parts = []
    digits = ""
    for character in compressed:
        if character.isdigit():
            digits += character
        elif digits:
            parts.append(character * int(digits))
            digits = ""
        else:
            parts.append(character)
    return "".join(parts)


def rolling_average(values, window):
    """Yield the mean of every window of `window` consecutive values."""
    if window <= 0 or window > len(values):
        raise ValueError("window must be between 1 and the number of values")
    total = sum(values[:window])
    yield total / window
    for index in range(window, len(values)):
        total += values[index] - values[index - window]
        yield total / window


def is_balanced(expression):
    """Return True when every bracket in `expression` is matched and nested."""
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for character in expression:
        if character in "([{":
            stack.append(character)
        elif character in pairs:
            if not stack or stack.pop() != pairs[character]:
                return False
    return not stack


def levenshtein(first, second):
    """Return the edit distance between two strings (insert, delete, substitute)."""
    if len(first) < len(second):
        first, second = second, first
    previous = list(range(len(second) + 1))
    for i, left in enumerate(first, start=1):
        current = [i]
        for j, right in enumerate(second, start=1):
            current.append(min(previous[j] + 1, current[j - 1] + 1,
                               previous[j - 1] + (left != right)))
        previous = current
    return previous[-1]


def topological_order(graph):
    """Order nodes so every edge points from an earlier node to a later one."""
    indegree = {node: 0 for node in graph}
    for node in graph:
        for neighbor in graph[node]:
            indegree[neighbor] += 1
    ready = sorted(node for node, degree in indegree.items() if degree == 0)
    order = []
    while ready:
        node = ready.pop(0)
        order.append(node)
        for neighbor in sorted(graph.get(node, ())):
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                ready.append(neighbor)
    if len(order) != len(graph):
        raise ValueError("graph contains a cycle")
    return order


def parse_ranges(text, maximum):
    """Parse '1-3,5,9-' into the explicit set of integers it denotes."""
    result = set()
    for part in text.split(","):
        bounds = part.split("-")
        if len(bounds) == 1:
            result.add(int(bounds[0]))
        else:
            start = int(bounds[0]) if bounds[0] else 1
            end = int(bounds[1]) if bounds[1] else maximum
            result.update(range(start, end + 1))
    return sorted(value for value in result if 1 <= value <= maximum)


def summarize_counts(counts, limit):
    """Return the `limit` most frequent items as (count, item) pairs."""
    ranked = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return [(count, item) for item, count in ranked[:limit]]
